const s = wb.getWorksheet('Sheet1');
for (let r = 7; r <= 32; r++) s.getRange(`E${r}`).setValue(`=LEN($D$5)-LEN(SUBSTITUTE($D$5,D${r},""))`);
const text = s.getRange('D5').getValues()[0][0];
const out = [];
let total = 0;
for (let r = 7; r <= 32; r++) {
  const c = s.getRange(`D${r}`).getValues()[0][0];
  const v = s.getRange(`E${r}`).getValues()[0][0];
  const hand = text.split(c).length - 1;
  total += hand;
  out.push(`${c}: ${v} (${typeof v}) text=${s.getRange(`E${r}`).getCell().getText?.()} hand=${hand} ${v === hand ? 'ok' : 'MISMATCH'}`);
}
log(out.join('\n'));
log(`len=${text.length} sumHand=${total}`);
